    function onRepayBorrow(address borrower) external {
        if (address(uToken) != msg.sender) revert AuthFailed();

        uint256 overdueBlocks = uToken.overdueBlocks();

        uint256 vouchersLength = vouchers[borrower].length;
        uint256 lastRepay = 0;
